<?php
require_once __DIR__.'/../includes/layout.php';$u=require_login('recruiter');
$offer=(int)($_GET['offer']??0);
$sql='SELECT a.id,a.status,a.applied_at,a.cover_letter,o.title,o.id offer_id,s.name,s.email,p.user_id student_id,p.university,p.program,p.city,p.skills,p.interests,p.bio,p.cv_path FROM applications a JOIN offers o ON o.id=a.offer_id JOIN users s ON s.id=a.student_id JOIN student_profiles p ON p.user_id=s.id WHERE o.recruiter_id=?';$args=[$u['id']];if($offer){$sql.=' AND o.id=?';$args[]=$offer;}$sql.=' ORDER BY a.applied_at DESC LIMIT 200';
$q=db()->prepare($sql);$q->execute($args);$rows=$q->fetchAll();page_header('Candidatures reçues');
?><p><a class="btn" href="<?=h(url('recruiter/offer_form.php'))?>">+ Nouvelle offre</a> <a href="<?=h(url('recruiter/offers.php'))?>">Gérer mes offres</a></p>
<?php foreach($rows as $r):?><div class="card"><span class="pill"><?=h($r['status'])?></span><h2><?=h($r['name'])?> — <?=h($r['title'])?></h2><p><?=h($r['email'])?> · <?=h($r['university'])?> · <?=h($r['program'])?> · <?=h($r['city'])?></p><p><b>Compétences :</b> <?=nl2br(h($r['skills']))?></p><p><b>Intérêts :</b> <?=nl2br(h($r['interests']))?></p><p><b>Présentation :</b> <?=nl2br(h($r['bio']))?></p><p><b>Motivation :</b> <?=nl2br(h($r['cover_letter']))?></p><?php if($r['cv_path']):?><a href="<?=h(url('download_cv.php?student_id='.$r['student_id'].'&application_id='.$r['id']))?>">Consulter le CV (PDF)</a><?php endif;?>
<div class="actions"><?php if($r['status']==='pending'):?><form method="post" action="<?=h(url('recruiter/decision.php'))?>"><?=csrf_field()?><input type="hidden" name="application_id" value="<?=h((string)$r['id'])?>"><button name="decision" value="interview">Inviter à un entretien</button><button name="decision" value="rejected" class="danger">Refuser</button></form><?php else:?><span>Décision enregistrée</span><?php endif;?></div></div><?php endforeach;?><?php if(!$rows):?><p>Aucune candidature reçue pour le moment.</p><?php endif;page_footer();?>